    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xDD0EF5EB6343D157ULL + 0xD3CB3D3A221B8F8EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0x9BB57D4DB2F0B95BULL + 0x964BED51CC854125ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseB(pNonce * 0xC641B6C6B68C5A1DULL + 0x8F7537494162731CULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0xAE61A3416F7497BBULL + 0x94661F5F504B2AC1ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseA(pNonce * 0xAB482FBAEDCE5063ULL + 0xB3A7C7E97A46E05BULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0xA711D821E7A16485ULL + 0xF6DA16D6D5CD4DA3ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseC(pNonce * 0xD9571646FED76FDBULL + 0xCE49AB25F9ACEA25ULL);
