            aCross = RotL64(aSource[((S_BLOCK1 - aIndex + 1948U)) & S_BLOCK1], 37U) ^ RotL64(pSnowLaneB[((S_BLOCK1 - aIndex + 3893U)) & S_BLOCK1], 3U);
