            aOrbiterA = (((aWandererI + RotL64(aScatter, 39U)) + RotL64(aCarry, 27U)) + 0x9E9AF786F3661C06ULL) + aOrbiterAssignSaltE[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterI = ((aWandererC + RotL64(aIngress, 23U)) + RotL64(aCarry, 39U)) + 0xBC7F0102715676C1ULL;
