            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0xD89117AA9B7E7782ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x142861D155592FB3ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x68F39F026BCBC36DULL), 23U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x43F17D0C2586CAF8ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0xEF1F06A198BC0B7CULL;
            aOrbiterH = RotL64((aOrbiterH * 0xD53D3A4411B4CDD9ULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0xC235A13330D7B42EULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xA845A31AF92811D8ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x65D9F4B5E5DAFBF9ULL), 37U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x54D49933C8E27E94ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0x5527F0F883F6081FULL) ^ aOrbiterUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xD121F438114F394DULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0xB04AD1B62F54C19DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x642F28FB137C4DC9ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x06DE84EA0C4F2DCFULL), 51U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0xEB817AE4709489E4ULL) + aOrbiterUpdateSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x1C3BC931E16F24B3ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xE055AE929A19665BULL), 43U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x960C35DE034FAA9FULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x3137952CA5E1BC97ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xC748D3CCDF7E28E1ULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x8EAB637DDA05F2CAULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0xBA6136A2D0993137ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xFC64FDE3C7F7DAB5ULL), 21U);
            //
            aIngress = RotL64(aOrbiterE, 11U) ^ aOrbiterG;
            aIngress = aIngress + (aOrbiterH ^ RotL64(aOrbiterI, 29U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterC, 46U));
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterK, 35U));
            aIngress = aIngress + (RotL64(aOrbiterB, 41U) ^ aOrbiterA);
