            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererH = aWandererH + (((RotL64(aIngress, 37U) + RotL64(aOrbiterK, 35U)) + aOrbiterA) + aNonceWordN);
