    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0x8B063F59F1ECC67DULL + 0xA7565C8C4AF1D2BCULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xCDB0AC81EE77C44BULL + 0xB023B2135544B3E4ULL);
