            aOrbiterD = (aWandererJ + RotL64(aCross, 28U)) + 0x0DAD4D60FBCDA7A8ULL;
            aOrbiterK = (((aWandererD + RotL64(aScatter, 57U)) + RotL64(aCarry, 23U)) + 0xDEFB5B7D49E8A2BEULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterB = (aWandererK + RotL64(aPrevious, 39U)) + 0x1AEEFB481C237A87ULL;
            aOrbiterA = (((aWandererF + RotL64(aCross, 53U)) + RotL64(aCarry, 5U)) + 0x7E1EEAA2A25BE0EDULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 20U)) & S_SALT1];
