            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x94253EC96474CDABULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0x09D93CA1EFC8408EULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x5B6241A747EC27ABULL), 57U);
            //
