            aOrbiterD = (aWandererH + RotL64(aIngress, 29U)) + 0x2EEC2A7C815260BAULL;
            aOrbiterC = (((aWandererG + RotL64(aCross, 12U)) + RotL64(aCarry, 19U)) + 0x4D6582E4D45776B7ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
