            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x2DDAF2B5FAA18081ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x0F47ECACE621AAB2ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x0C1E80BEC64ABABBULL), 3U);
            //
