            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x41D4088C50BC88B6ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 29U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0xEEF613AFE4505BC4ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 6U)) & S_SALT1];
