            //
            aIngress = (RotL64(aWindLaneA[((aIndex + 6493U)) & S_BLOCK1], 11U) ^ RotL64(aWindLaneB[((aIndex + 4085U)) & S_BLOCK1], 43U));
            aIngress ^= (RotL64(aWoodLaneA[((aIndex + 7523U)) & S_BLOCK1], 29U) ^ RotL64(aPoisonLaneB[((aIndex + 7117U)) & S_BLOCK1], 60U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 2015U)) & S_BLOCK1], 23U) ^ RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 4247U)) & S_BLOCK1], 13U));
            aCross ^= (RotL64(aPlasmaLaneD[((S_BLOCK1 - aIndex + 2048U)) & S_BLOCK1], 37U) ^ RotL64(aPlasmaLaneC[((aIndex + 5091U)) & S_BLOCK1], 50U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 41U) ^ RotL64(aCross, 56U)) + (RotL64(aIngress, 5U) + RotL64(aCarry, 29U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterC = ((aWandererH + RotL64(aIngress, 47U)) + RotL64(aCarry, 35U)) + 0x0E5693D2CF6CDFB4ULL;
            aOrbiterE = (((aWandererA + RotL64(aPrevious, 53U)) + RotL64(aCarry, 13U)) + 0x22A1078648C6E75EULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 3U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aScatter, 29U)) + 0x1B94CE03BC4AD428ULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterI = ((aWandererI + RotL64(aCross, 3U)) + RotL64(aCarry, 51U)) + 0xA4ED96353B371234ULL;
            aOrbiterA = (aWandererB + RotL64(aIngress, 22U)) + 0xB560536C27EE7023ULL;
            aOrbiterB = (aWandererJ + RotL64(aCross, 13U)) + 0x451D8305176CC410ULL;
            aOrbiterK = (aWandererD + RotL64(aPrevious, 41U)) + 0xD2F5C16459782D68ULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0xCCE9A4D9407073CFULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0x279406CF39D91D57ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xD9DF3BCAC7B7309DULL), 57U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterA) + 0x6459C49615E2590BULL) + aKeyRotateAOrbiterUpdateSaltD[((aIndex + 4U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterI) ^ 0x8616BBED8B9D73EDULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x2B0F7B9955F81D39ULL), 29U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x4FCC4C4A57E861EFULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0xC6346A691BEC1323ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x9B5DB676E4D912FDULL), 5U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x9F23DBA6505A9577ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x687F106E26540CC7ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xDD9181CBA7F4A19FULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x1B52D2821433C25BULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xD8111963A527F637ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x6390DA2AA133DFB1ULL), 21U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x377EB962F167D308ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0xB4970487E42259DEULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x5CA5D121355B69E3ULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x6B9AB385D49A14DFULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0xE8629AEB54D7B4F9ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xD02AA555DFC895C5ULL), 13U);
            //
            aIngress = aOrbiterB ^ RotL64(aOrbiterE, 5U);
            aIngress = aIngress + (RotL64(aOrbiterC, 43U) ^ aOrbiterA);
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterI, 21U));
            aIngress = aIngress + RotL64(aOrbiterF, 13U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererF = aWandererF + ((((RotL64(aScatter, 5U) + RotL64(aOrbiterK, 11U)) + aOrbiterI) + RotL64(aCarry, 27U)) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 16U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aCross, 53U) + aOrbiterC) + RotL64(aOrbiterE, 37U));
            aWandererI = aWandererI + ((RotL64(aIngress, 30U) + RotL64(aOrbiterB, 60U)) + aOrbiterF);
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 47U) + RotL64(aOrbiterC, 29U)) + aOrbiterI);
            aWandererJ = aWandererJ + ((RotL64(aScatter, 21U) + aOrbiterI) + RotL64(aOrbiterA, 43U));
            aWandererA = aWandererA ^ (((RotL64(aIngress, 39U) + aOrbiterC) + RotL64(aOrbiterB, 21U)) + aKeyRotateAWandererUpdateSaltC[(((31U - aIndex) + 29U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aPrevious, 13U) + aOrbiterA) + RotL64(aOrbiterB, 3U)) + RotL64(aCarry, 41U));
