            aOrbiterF = (aWandererG + RotL64(aPrevious, 27U)) + 0xE1C33B26404EED99ULL;
            aOrbiterG = (aWandererE + RotL64(aScatter, 21U)) + 0x4937D16701B8584FULL;
            aOrbiterD = ((aWandererI + RotL64(aPrevious, 51U)) + RotL64(aCarry, 47U)) + 0x6F94CAED40A1B9B1ULL;
            aOrbiterA = ((aWandererC + RotL64(aScatter, 58U)) + RotL64(aCarry, 35U)) + 0x70EF161E5CA67B06ULL;
            aOrbiterC = (((aWandererA + RotL64(aCross, 11U)) + RotL64(aCarry, 5U)) + 0xB18F699A7DEA7F26ULL) + aKeyRotateBOrbiterAssignSaltF[((aIndex + 6U)) & S_SALT1];
