            aOrbiterF = ((aOrbiterF ^ aOrbiterJ) ^ 0x7EABF52BEA3E9B0AULL) ^ aKeyRotateBOrbiterUpdateSaltC[(((31U - aIndex) + 12U)) & S_SALT1];
